/* deps/veracrypt §E1 — known-answer test for the stripped VeraCrypt crypto subset.
 * Validates the cross-built ciphers/hashes against published vectors, proving the
 * strip kept a CORRECT crypto core (not just one that links).  musl-static → runs on
 * the build host. */
#include <stdio.h>
#include <string.h>
#include "Crypto/Aes.h"
#include "Crypto/Sha2.h"

static int chk(const char *name, const unsigned char *got,
               const unsigned char *want, int n) {
    if (memcmp(got, want, n) == 0) { printf("  %s KAT PASS\n", name); return 1; }
    printf("  %s KAT FAIL\n", name);
    return 0;
}

int main(void) {
    int ok = 1;

    /* AES-256 (FIPS-197 example): single-block ECB encrypt. */
    static const unsigned char key[32] = {
        0x00,0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,0x09,0x0a,0x0b,0x0c,0x0d,0x0e,0x0f,
        0x10,0x11,0x12,0x13,0x14,0x15,0x16,0x17,0x18,0x19,0x1a,0x1b,0x1c,0x1d,0x1e,0x1f };
    static const unsigned char pt[16] = {
        0x00,0x11,0x22,0x33,0x44,0x55,0x66,0x77,0x88,0x99,0xaa,0xbb,0xcc,0xdd,0xee,0xff };
    static const unsigned char ct_want[16] = {
        0x8e,0xa2,0xb7,0xca,0x51,0x67,0x45,0xbf,0xea,0xfc,0x49,0x90,0x4b,0x49,0x60,0x89 };
    unsigned char ct[16];
    aes_encrypt_ctx cx[1];
    aes_encrypt_key256(key, cx);
    aes_encrypt(pt, ct, cx);
    ok &= chk("AES-256", ct, ct_want, 16);

    /* SHA-512("abc"). */
    static const unsigned char sha_want[64] = {
        0xdd,0xaf,0x35,0xa1,0x93,0x61,0x7a,0xba,0xcc,0x41,0x73,0x49,0xae,0x20,0x41,0x31,
        0x12,0xe6,0xfa,0x4e,0x89,0xa9,0x7e,0xa2,0x0a,0x9e,0xee,0xe6,0x4b,0x55,0xd3,0x9a,
        0x21,0x92,0x99,0x2a,0x27,0x4f,0xc1,0xa8,0x36,0xba,0x3c,0x23,0xa3,0xfe,0xeb,0xbd,
        0x45,0x4d,0x44,0x23,0x64,0x3c,0xe8,0x0e,0x2a,0x9a,0xc9,0x4f,0xa5,0x4c,0xa4,0x9f };
    unsigned char h[64];
    sha512(h, (const unsigned char *)"abc", 3);
    ok &= chk("SHA-512", h, sha_want, 64);

    printf("VC-CRYPTO-KAT: %s\n", ok ? "ALL PASS" : "FAIL");
    return ok ? 0 : 1;
}
